namespace FramePilot {
 public sealed class GameStoreOverview {public string Name,Summary,ReleaseDate;}
 public static class SteamArtwork {
  static readonly HttpClient http=new HttpClient{Timeout=TimeSpan.FromSeconds(8)};
  static readonly ConcurrentDictionary<string,Lazy<Task<string>>> pending=new ConcurrentDictionary<string,Lazy<Task<string>>>();
  static readonly ConcurrentDictionary<string,Lazy<Task<string>>> libraryPending=new ConcurrentDictionary<string,Lazy<Task<string>>>();
  internal static Func<string,CancellationToken,Task<HttpResponseMessage>> ResponseFactory;
  internal static string TestCacheRoot;
  static readonly string[] Types={"cover","hero","header","logo","icon"};
  static SteamArtwork(){http.DefaultRequestHeaders.UserAgent.ParseAdd("FramePilot/3.1");foreach(string endpoint in new[]{"https://cdn.cloudflare.steamstatic.com","https://steamcdn-a.akamaihd.net","https://www.steamgriddb.com","https://cdn.steamgriddb.com"})ServicePointManager.FindServicePoint(new Uri(endpoint)).ConnectionLimit=8;}
  public static string CacheRoot { get { return TestCacheRoot??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FramePilot","artwork","steam"); } }
  static byte[] keyEntropy { get { return Encoding.UTF8.GetBytes("FramePilot-SteamGridDB-v1"); } }
  public static void SaveApiKey(string key){using(var root=Registry.CurrentUser.CreateSubKey(@"Software\FramePilot")){if(string.IsNullOrWhiteSpace(key)){root.DeleteValue("SteamGridDBApiKey",false);return;}byte[] encrypted=ProtectedData.Protect(Encoding.UTF8.GetBytes(key.Trim()),keyEntropy,DataProtectionScope.CurrentUser);root.SetValue("SteamGridDBApiKey",Convert.ToBase64String(encrypted),RegistryValueKind.String);}}
  public static string GetApiKey(){string env=Environment.GetEnvironmentVariable("STEAMGRIDDB_API_KEY");if(!string.IsNullOrWhiteSpace(env))return env.Trim();try{using(var root=Registry.CurrentUser.OpenSubKey(@"Software\FramePilot")){string saved=root==null?null:Convert.ToString(root.GetValue("SteamGridDBApiKey"));if(!string.IsNullOrWhiteSpace(saved))return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(saved),keyEntropy,DataProtectionScope.CurrentUser));}}catch{}return null;}
  public static string FindLocal(FoundGame game,string type){
   if(game==null||game.Source!="Steam"||!IsAppId(game.AppId)||!Types.Contains(type))return null;
   var dirs=new List<string>();if(!string.IsNullOrWhiteSpace(game.SteamRoot)){dirs.Add(Path.Combine(game.SteamRoot,"appcache","librarycache"));string users=Path.Combine(game.SteamRoot,"userdata");try{foreach(string user in Directory.GetDirectories(users).Take(64))dirs.Add(Path.Combine(user,"config","grid"));}catch{}}
   string[] suffixes=type=="cover"?new[]{"_library_600x900_2x","_library_600x900","p",""}:type=="hero"?new[]{"_library_hero","_hero"}:type=="header"?new[]{"_header"}:type=="logo"?new[]{"_logo"}:new[]{"_icon"};string[] extensions={".jpg",".jpeg",".png",".bmp"};
   foreach(string dir in dirs){foreach(string suffix in suffixes)foreach(string ext in extensions){string file=Path.Combine(dir,game.AppId+suffix+ext);if(IsValid(file))return file;}try{foreach(string file in Directory.GetFiles(dir,game.AppId+"*.*").Take(100)){string name=Path.GetFileNameWithoutExtension(file).ToLowerInvariant();if((type=="cover"&&(name.Contains("library_600x900")||name==game.AppId+"p"||name==game.AppId))||(type=="hero"&&name.Contains("hero"))||(type=="header"&&name.Contains("header"))||(type=="logo"&&name.Contains("logo"))||(type=="icon"&&name.Contains("icon")))if(IsValid(file))return file;}}catch{}}
   return null;
  }
  public static Task<string> GetCoverAsync(FoundGame game,CancellationToken token){if(game==null||string.IsNullOrWhiteSpace(game.Name))return Task.FromResult<string>(null);string key=game.Source=="Steam"&&IsAppId(game.AppId)?"steam:"+game.AppId:"name:"+NormalizeName(game.Name);if(key.EndsWith(":",StringComparison.Ordinal))return Task.FromResult<string>(null);var lazy=pending.GetOrAdd(key,k=>new Lazy<Task<string>>(()=>Task.Run(()=>DownloadCoverAsync(game,token))));return AwaitAndRelease(key,lazy.Value);}
  public static async Task<GameStoreOverview> GetStoreOverviewAsync(FoundGame game,CancellationToken token){
   if(game==null||string.IsNullOrWhiteSpace(game.Name))return null;try{string appId=game.Source=="Steam"&&IsAppId(game.AppId)?game.AppId:null;
    if(appId==null){string search=await StoreGet("https://store.steampowered.com/api/storesearch/?term="+Uri.EscapeDataString(game.Name)+"&l=english&cc=US",token).ConfigureAwait(false);if(search==null)return null;var root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(search);object raw;var items=root!=null&&root.TryGetValue("items",out raw)?raw as ArrayList:null;if(items==null)return null;var exact=items.Cast<object>().OfType<Dictionary<string,object>>().Where(x=>{object n,t;return x.TryGetValue("name",out n)&&NormalizeName(Convert.ToString(n))==NormalizeName(game.Name)&&(!x.TryGetValue("type",out t)||string.Equals(Convert.ToString(t),"app",StringComparison.OrdinalIgnoreCase));}).ToArray();if(exact.Length!=1)return null;object id;if(!exact[0].TryGetValue("id",out id)||!Convert.ToString(id).All(char.IsDigit))return null;appId=Convert.ToString(id);}
    string details=await StoreGet("https://store.steampowered.com/api/appdetails?appids="+Uri.EscapeDataString(appId)+"&l=english&cc=US",token).ConfigureAwait(false);if(details==null)return null;var result=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(details);object entryRaw;var entry=result!=null&&result.TryGetValue(appId,out entryRaw)?entryRaw as Dictionary<string,object>:null;object success,dataRaw;if(entry==null||!entry.TryGetValue("success",out success)||!Convert.ToBoolean(success)||!entry.TryGetValue("data",out dataRaw))return null;var data=dataRaw as Dictionary<string,object>;if(data==null)return null;Func<string,string> get=k=>{object v;return data.TryGetValue(k,out v)?Convert.ToString(v):null;};string summary=get("short_description");if(!string.IsNullOrWhiteSpace(summary)){summary=WebUtility.HtmlDecode(Regex.Replace(summary,"<[^>]+>"," "));summary=Regex.Replace(summary,"\\s+"," ").Trim();}var release=data.ContainsKey("release_date")?data["release_date"] as Dictionary<string,object>:null;object date;return new GameStoreOverview{Name=get("name"),Summary=summary,ReleaseDate=release!=null&&release.TryGetValue("date",out date)?Convert.ToString(date):null};
   }catch(OperationCanceledException){throw;}catch{return null;}
  }
  static async Task<string> StoreGet(string url,CancellationToken token){try{using(var response=await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,token).ConfigureAwait(false)){if(!response.IsSuccessStatusCode)return null;long? length=response.Content.Headers.ContentLength;if(length.HasValue&&length.Value>1024*1024)return null;string value=await response.Content.ReadAsStringAsync().ConfigureAwait(false);return value.Length<=1024*1024?value:null;}}catch(OperationCanceledException){throw;}catch{return null;}}
  public static Task<string> GetLibraryImageAsync(FoundGame game,CancellationToken token){
   if(game==null||string.IsNullOrWhiteSpace(game.Name))return Task.FromResult<string>(null);
   string key=game.Source+":"+(game.Source=="Steam"&&IsAppId(game.AppId)?game.AppId:NormalizeName(game.Name));
   var lazy=libraryPending.GetOrAdd(key,k=>new Lazy<Task<string>>(()=>Task.Run(()=>DownloadLibraryImageAsync(game,token))));return ReleaseLibrary(key,lazy);
  }
  static async Task<string> ReleaseLibrary(string key,Lazy<Task<string>> task){try{return await task.Value.ConfigureAwait(false);}finally{((ICollection<KeyValuePair<string,Lazy<Task<string>>>>)libraryPending).Remove(new KeyValuePair<string,Lazy<Task<string>>>(key,task));}}
  static async Task<string> DownloadLibraryImageAsync(FoundGame game,CancellationToken token){
   if(game==null||string.IsNullOrWhiteSpace(game.Name))return null;
   bool steam=game.Source=="Steam"&&IsAppId(game.AppId);if(steam){string local=FindLocal(game,"header")??FindLocal(game,"hero")??FindLocal(game,"cover");if(IsValid(local))return local;}
   string cache=Path.Combine(CacheRoot,(steam?game.AppId:"name_"+NameHash(game.Name))+"_hero.jpg");if(IsValid(cache))return cache;
   try{Directory.CreateDirectory(CacheRoot);
    // Wide cards need the small header first, rather than waiting for a large
    // hero or two optional API calls before trying Steam's direct image.
    if(steam){foreach(string url in new[]{"https://cdn.cloudflare.steamstatic.com/steam/apps/"+game.AppId+"/header.jpg","https://cdn.cloudflare.steamstatic.com/steam/apps/"+game.AppId+"/library_hero.jpg"}){string result=await DownloadImage(url,cache,token).ConfigureAwait(false);if(result!=null)return result;}}
    string key=GetApiKey();if(!string.IsNullOrWhiteSpace(key)){string url=await SteamGridDbImageUrl(game,key,"heroes",token).ConfigureAwait(false);if(url!=null){string result=await DownloadImage(url,cache,token).ConfigureAwait(false);if(result!=null)return result;}}
   }catch(OperationCanceledException){throw;}catch{}return await GetCoverAsync(game,token).ConfigureAwait(false);
  }
  static async Task<string> AwaitAndRelease(string key,Task<string> task){try{return await task.ConfigureAwait(false);}finally{Lazy<Task<string>> ignored;pending.TryRemove(key,out ignored);}}
  static async Task<string> DownloadCoverAsync(FoundGame game,CancellationToken token){bool steam=game.Source=="Steam"&&IsAppId(game.AppId);if(steam){string local=FindLocal(game,"cover")??FindLocal(game,"hero")??FindLocal(game,"header");if(IsValid(local))return local;}string cacheId=steam?game.AppId:"name_"+NameHash(game.Name);string cache=Path.Combine(CacheRoot,cacheId+"_cover.jpg");if(IsValid(cache))return cache;try{Directory.CreateDirectory(CacheRoot);string key=GetApiKey();if(!string.IsNullOrWhiteSpace(key)){string sgdb=await SteamGridDbCoverUrl(game,key,token).ConfigureAwait(false);if(!string.IsNullOrWhiteSpace(sgdb)){string path=await DownloadImage(sgdb,cache,token).ConfigureAwait(false);if(path!=null)return path;}}if(steam){string[] urls={"https://cdn.cloudflare.steamstatic.com/steam/apps/"+game.AppId+"/library_600x900.jpg","https://cdn.cloudflare.steamstatic.com/steam/apps/"+game.AppId+"/header.jpg","https://cdn.cloudflare.steamstatic.com/steam/apps/"+game.AppId+"/library_hero.jpg","https://steamcdn-a.akamaihd.net/steam/apps/"+game.AppId+"/header.jpg"};foreach(string url in urls){token.ThrowIfCancellationRequested();string path=await DownloadImage(url,cache,token).ConfigureAwait(false);if(path!=null)return path;}}}catch(OperationCanceledException){throw;}catch{}return null;}
  static string NormalizeName(string name){if(string.IsNullOrWhiteSpace(name))return "";string value=name.Normalize(NormalizationForm.FormKC).ToLowerInvariant();var chars=value.Where(char.IsLetterOrDigit).ToArray();return new string(chars);}
  static string NameHash(string name){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(NormalizeName(name)))).Replace("-","").ToLowerInvariant();}
  internal static Task<string> SteamGridDbCoverUrl(FoundGame game,string key,CancellationToken token){return SteamGridDbImageUrl(game,key,"grids",token);}
  static async Task<string> SteamGridDbImageUrl(FoundGame game,string key,string asset,CancellationToken token){try{string gameId=null;if(game.Source=="Steam"&&IsAppId(game.AppId))gameId=game.AppId;else{string query=Uri.EscapeDataString(game.Name.Trim());string search=await SteamGridDbRequest("https://www.steamgriddb.com/api/v2/search/autocomplete/"+query,key,token).ConfigureAwait(false);if(search==null)return null;var parsed=ParseSteamGridDb(search);var matches=parsed.Where(x=>x.Name!=null&&NormalizeName(x.Name)==NormalizeName(game.Name)&&x.Types.Contains("steam",StringComparer.OrdinalIgnoreCase)).ToArray();if(matches.Select(x=>x.Id).Distinct().Count()!=1)return null;gameId=matches[0].Id;}
   string route=game.Source=="Steam"&&IsAppId(game.AppId)?asset+"/steam/":asset+"/game/";string dimensions=asset=="grids"?"?dimensions=600x900&types=static&nsfw=false":"?dimensions=1920x620&nsfw=false";string json=await SteamGridDbRequest("https://www.steamgriddb.com/api/v2/"+route+gameId+dimensions,key,token).ConfigureAwait(false);if(json==null)return null;var root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);object raw;if(root==null||!root.TryGetValue("data",out raw))return null;var list=raw as ArrayList;if(list==null)return null;foreach(var entry in list){var item=entry as Dictionary<string,object>;object url;Uri parsedUrl;if(item!=null&&item.TryGetValue("url",out url)&&Uri.TryCreate(Convert.ToString(url),UriKind.Absolute,out parsedUrl)&&parsedUrl.Scheme==Uri.UriSchemeHttps)return parsedUrl.ToString();}}catch(OperationCanceledException){throw;}catch{}return null;}
  sealed class SgdbGame {public string Id,Name;public List<string> Types=new List<string>();}
  static List<SgdbGame> ParseSteamGridDb(string json){var result=new List<SgdbGame>();var root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);object raw;if(root==null||!root.TryGetValue("data",out raw))return result;var list=raw as ArrayList;if(list==null)return result;foreach(object value in list){var item=value as Dictionary<string,object>;if(item==null)continue;object nested;if(item.TryGetValue("data",out nested))item=nested as Dictionary<string,object>;if(item==null)continue;object id,name,types;if(!item.TryGetValue("id",out id)||!item.TryGetValue("name",out name))continue;var game=new SgdbGame{Id=Convert.ToString(id),Name=Convert.ToString(name)};if(item.TryGetValue("types",out types)){var array=types as ArrayList;if(array!=null)game.Types=array.Cast<object>().Select(Convert.ToString).ToList();else{var strings=types as string[];if(strings!=null)game.Types=strings.ToList();}}if(!string.IsNullOrWhiteSpace(game.Id)&&game.Id.All(char.IsDigit))result.Add(game);}return result;}
  static async Task<string> SteamGridDbRequest(string url,string key,CancellationToken token){try{if(ResponseFactory!=null){using(var mocked=await ResponseFactory(url,token).ConfigureAwait(false)){if(!mocked.IsSuccessStatusCode)return null;return await mocked.Content.ReadAsStringAsync().ConfigureAwait(false);}}using(var request=new HttpRequestMessage(HttpMethod.Get,url)){request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",key);using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token).ConfigureAwait(false)){if(!response.IsSuccessStatusCode)return null;return await response.Content.ReadAsStringAsync().ConfigureAwait(false);}}}catch(OperationCanceledException){throw;}catch{return null;}}
  internal static async Task<string> GetCachedDownload(string url,string cache,CancellationToken token){if(IsValid(cache))return cache;return await DownloadImage(url,cache,token).ConfigureAwait(false);}
  internal static async Task<string> DownloadImage(string url,string cache,CancellationToken token){string temp=null;try{HttpResponseMessage received=ResponseFactory==null?await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,token).ConfigureAwait(false):await ResponseFactory(url,token).ConfigureAwait(false);using(var response=received){if(!response.IsSuccessStatusCode)return null;long? length=response.Content.Headers.ContentLength;if(length.HasValue&&length.Value>8*1024*1024)return null;byte[] bytes=await response.Content.ReadAsByteArrayAsync().ConfigureAwait(false);if(bytes.Length==0||bytes.Length>8*1024*1024||!IsValidImage(bytes))return null;temp=cache+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllBytes(temp,bytes);if(!IsValid(temp))return null;if(File.Exists(cache))File.Replace(temp,cache,null);else File.Move(temp,cache);return cache;}}catch(OperationCanceledException){throw;}catch{return null;}finally{if(temp!=null&&File.Exists(temp))try{File.Delete(temp);}catch{}}}
  static bool IsAppId(string id){long value;return long.TryParse(id,out value)&&value>0&&id.Length<=12;}
  static bool IsValid(string path){if(string.IsNullOrWhiteSpace(path))return false;try{if(!File.Exists(path)||new FileInfo(path).Length<128||new FileInfo(path).Length>8*1024*1024)return false;using(var image=Image.FromFile(path))return image.Width>0&&image.Height>0&&image.Width<=10000&&image.Height<=10000;}catch{return false;}}
  static bool IsValidImage(byte[] bytes){try{using(var stream=new MemoryStream(bytes))using(var image=Image.FromStream(stream))return image.Width>0&&image.Height>0&&image.Width<=10000&&image.Height<=10000;}catch{return false;}}
 }
}
